def tag(s,c=''):return f'<span class="tag {c}">{s}</span>'
def field(k,v):return f'<div class="field"><div class="label">{k}</div><div class="valuebox">{v}</div></div>'
def tree(title,items):return f'<h3>{title}</h3><div class="search">⌕　搜索名称或 ID</div>'+''.join(f'<div class="item {"selected" if n==0 else ""}"><span style="color:#8aa3af">◇</span>{name}</div>' for n,name in enumerate(items))
def table(head,rows,widths=None):
 cols='<colgroup>'+''.join(f'<col style="width:{w}%">' for w in widths)+'</colgroup>' if widths else ''
 return '<div class="tablewrap"><table>'+cols+'<thead><tr>'+''.join('<th>'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr'+(' class="selected"' if i==0 else '')+'>'+''.join('<td'+(' class="num"' if re.match(r'^[+−\-]?\d+(?:[.,]\d+)?(?:\s*(?:°C|K|L|%|s))?$',re.sub('<[^>]+>','',str(x)).strip()) else '')+'>'+str(x)+'</td>' for x in row)+'</tr>' for i,row in enumerate(rows))+'</tbody></table></div>'
def title(t,sub,actions='保存草稿',status='草稿 · r12'):
 return f'<div class="title"><div><h1>{t}</h1><div class="subtitle">{sub}</div></div><div class="spacer"></div><div class="row">{tag(status)}<button class="primary">{actions}</button></div></div>'
def tabs(names):return '<div class="tabs">'+''.join(f'<span class="{"active" if i==0 else ""}">{x}</span>' for i,x in enumerate(names))+'</div>'
def metric(k,v,u,meta='',c=''):return f'<div class="metric"><div class="label">{k}</div><div class="number" style="{c}">{v}<span class="unit"> {u}</span></div><div class="meta">{meta}</div></div>'
def inspector(t,fields,extra=''):return '<h3>'+t+'</h3>'+''.join(field(a,b) for a,b in fields)+extra
