def save(pid,name,tr,main,ins,ctx='编辑模型 · model-04',overlay=''):
 nav=['项目','建模','场景','逻辑','运行','复盘'];act=1 if int(pid[1:])<7 else 2 if int(pid[1:])<11 else 3 if int(pid[1:])<19 else 4 if int(pid[1:])<24 else 5
 s=f'<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>{pid} {name}</title><style>{CSS}</style><body><div class="top"><span class="brand">演界 <span style="font-size:11px;letter-spacing:1px;color:#8dbfc5">SIMULATION STUDIO</span></span><span class="dim">/</span><span>临江危化品园区 · 联合处置演练</span><span class="spacer"></span><span class="dim small">离线工作区</span><span class="small">主控　林教官</span></div><aside class="rail">'+''.join(f'<div class="nav {"active" if i==act else ""}"><b>{["▦","◇","▧","⌘","▷","◷"][i]}</b>{x}</div>' for i,x in enumerate(nav))+f'</aside><div class="context"><strong>{name}</strong><span class="sep">/</span><span class="small">{ctx}</span><span class="spacer"></span>{tag(pid)}<span class="muted">布局 1920 × 1200</span></div><aside class="tree">{tr}</aside><main class="main">{main}</main><aside class="inspector">{ins}</aside><footer class="footer"><span>● 数据与页面上下文一致</span><span>空间坐标：park-ENU · m</span><span class="spacer"></span><span>{pid} · 指定状态设计参考　/　业务数据：mock ui-0.4</span></footer>{overlay}</body></html>'
 def button_size(m):
  attrs,label=m.groups(); plain=re.sub('<[^>]+>','',label);w=max(72,min(300,sum(15 if ord(c)>255 else 8 for c in plain)+30))
  if 'style=' not in attrs:attrs+=f' style="width:{w}px;flex:0 0 {w}px"'
  return '<button'+attrs+'>'+label+'</button>'
 s=re.sub(r'<button([^>]*)>(.*?)</button>',button_size,s)
 (O/f'{pid}.html').write_text(s);screens.append({'pageId':pid,'title':name,'html':pid+'.html','image':pid+'.png'})
