# Scene map schematic, data-driven entity markers
def mapview(state,height=610,selected='F01',editing=False):
 pos={e['id']:e for e in state};marks=''
 for eid,e in pos.items():
  if e.get('position') is None:continue
  x,y,z=e['position']; x=80+x*1.18;y=height-80-y*.8
  coloc=sum(q.get('position')==e['position'] for q in state)>1
  ax,ay=x,y
  if coloc and eid=='V01':x-=12;y+=12
  if coloc and eid=='V02':x+=12;y-=12
  color='#c65c49' if e['classId']=='Fire' else '#087f8c' if e['classId']=='FoamTruck' else '#667d90'
  shape=(f'<line x1="{ax}" y1="{ay}" x2="{x}" y2="{y}" stroke="#087f8c" stroke-width="1"/>' if coloc else '')+f'<circle cx="{x}" cy="{y}" r="10" fill="{color}" stroke="white" stroke-width="3"/>'
  if eid==selected:shape+=f'<circle cx="{x}" cy="{y}" r="20" fill="none" stroke="{color}" stroke-width="2"/>'
  text=f'{eid} · {e["name"]}'
  if e['classId']=='Fire':text+=f' {e["temperature"]:g}°C'
  # hand place labels to prevent overlapping trucks
  dx,dy={'F01':(24,-70),'V01':(10,58),'V02':(-90,-34),'V03':(-50,34),'S01':(-18,-30)}.get(eid,(16,-23))
